Definition appb (r : L5.range) : bool :=
  Z.leb 0 (fst r) && (Z.leb (fst r + snd r) BIGSHADOW_LO || Z.leb BIGSHADOW_HI (fst r)) && Z.leb (fst r + snd r) (2 ^ 47).
